-- Question bank v3: ~1000 generated + curated questions, no easy tier.
-- Positions 1-10 carry the ten hand-written v2 questions; the rest are
-- template-generated with computed answers and explanations. Competitions
-- sample a stratified 30 at creation (config.question_ids).
select 3, position, category, difficulty, prompt, options, correct_index, explanation
from questions where bank_version = 2 and position <= 10;

